/* html2canvas 1.4.1 loader
 * The application keeps this file local, but loads the library from cdnjs so the
 * PNG export works without shipping a 200 KB minified bundle in this repository.
 * No user photo/data is sent by this request; it only downloads the JavaScript library.
 */
(function () {
  var src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
  var s = document.createElement('script');
  s.src = src;
  s.async = false;
  s.crossOrigin = 'anonymous';
  document.head.appendChild(s);
})();
